// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(v < 2**255);
        Reverter reverter = new Reverter();
        bool ok = true;
        try c.transfer(from, address(reverter), _tos, v) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
contract Reverter {
    function () external payable {
        if (msg.data.length >= 4) {
            bytes4 selector;
            assembly {
                calldatacopy(0, 0, 4)
                selector := mload(0)
            }
            assembly {
                let free_mem_ptr := mload(0x40)
                mstore(free_mem_ptr, selector)
                revert(free_mem_ptr, 4)
            }
        } else {
            revert("no selector");
        }
    }
}
